import sys

ISO='/app/alpine.iso'
SECTOR=2048

def read_at(f,lba,size):
    f.seek(lba*SECTOR)
    return f.read(size)

def parse_record(data,off):
    length=data[off]
    if length<33: return None
    name_len=data[off+32]
    name=data[off+33:off+33+name_len].split(b';')[0].decode('latin1')
    ext_lba=int.from_bytes(data[off+2:off+6],'little')
    size=int.from_bytes(data[off+10:off+14],'little')
    is_dir=bool(data[off+25]&2)
    return {'name':name,'lba':ext_lba,'size':size,'is_dir':is_dir}

def list_dir(f,lba,size):
    data=read_at(f,lba,size)
    entries=[]; off=0
    while off<len(data):
        length=data[off]
        if length==0:
            off=(off//SECTOR+1)*SECTOR
            continue
        rec=parse_record(data,off)
        if rec: entries.append(rec)
        off+=length
    return entries

def root_dir(f):
    pvd=read_at(f,16,SECTOR)
    return parse_record(pvd,156)

def find(f,path):
    parts=[p for p in path.split('/') if p]
    cur=root_dir(f)
    for part in parts:
        if not cur['is_dir']:
            raise NotADirectoryError(cur['name'])
        entries=list_dir(f,cur['lba'],cur['size'])
        nxt=None
        for e in entries:
            if e['name'].lower()==part.lower():
                nxt=e; break
        if nxt is None:
            raise FileNotFoundError('not found: '+part)
        cur=nxt
    return cur

def main():
    f=open(ISO,'rb')
    cmd=sys.argv[1]
    if cmd=='list':
        rec=find(f,sys.argv[2])
        for e in list_dir(f,rec['lba'],rec['size']):
            print(('D' if e['is_dir'] else 'F'), e['name'], e['lba'], e['size'])
    elif cmd=='cat':
        rec=find(f,sys.argv[2])
        data=read_at(f,rec['lba'],rec['size'])
        sys.stdout.buffer.write(data)
    elif cmd=='extract':
        rec=find(f,sys.argv[2])
        data=read_at(f,rec['lba'],rec['size'])
        with open(sys.argv[3],'wb') as o:
            o.write(data)
        print('wrote',sys.argv[3],rec['size'])

main()
